f = open('task26_19.txt')
n = int(f.readline())
points = {}
for _ in range(n):
    row, col = map(int, f.readline().split())
    if row not in points:
        points[row] = []
    points[row].append(col)
max_lines = 0
best_row = 0
for row, cols in points.items():
    cols = sorted(set(cols))
    lines = 0
    i = 0
    while i < len(cols):
        j = i
        while j + 1 < len(cols) and cols[j+1] == cols[j] + 1:
            j += 1
        if j - i + 1 >= 3:
            lines += 1
        i = j + 1
    if lines > max_lines or (lines == max_lines and row > best_row):
        max_lines = lines
        best_row = row
print(max_lines, best_row)
